def solve():
    n = 6
    seq = [0] * (2 * n)

    def backtrack(v):
        if v == 0:
            return True
        for i in range(2 * n - v - 1):
            if seq[i] == 0 and seq[i + v + 1] == 0:
                seq[i] = v
                seq[i + v + 1] = v
                if backtrack(v - 1):
                    return True
                seq[i] = 0
                seq[i + v + 1] = 0
        return False

    if backtrack(n):
        print(seq)
    else:
        print("UNSATISFIABLE")

solve()
